def _bench_with_launch_args(self, launcher, launch_args, reset_args, with_profiler=None, **kwargs):
    device_interface = self.get_device_interface()
    stream = device_interface.get_raw_stream(device_interface.current_device())

    def kernel_call():
        cloned_args, cloned_kwargs = self.clone_args(*launch_args, **kwargs)
        self.reset_to_zero_args(*reset_args, **kwargs)
        launcher(*cloned_args, **cloned_kwargs, stream=stream)
    if with_profiler is None:
        with_profiler = self.inductor_meta.get('profile_bandwidth_with_do_bench_using_profiling', False)
    if with_profiler and (not npu_profiler_session_active()):
        return do_bench_using_profiling_npu(kernel_call, rep=1)
    return benchmarker.benchmark_gpu(kernel_call, rep=1, device_type='npu', is_vetted_benchmarking=True)

