class _PeakMemFakeNode:

    def __init__(self, name: str) -> None:
        self.name = name
        self.scheduler = object()
        self._outputs: list = []
        self.mpi_node = SimpleNamespace(pred_buffers=set())
        self.snodes: list | None = None

    def get_name(self) -> str:
